const body = $input.first().json.body || $input.first().json;

const bookName = (body.book_name || 'Unknown Book').replace(/[\/\\:*?"<>|]/g, '_').trim();
const author = (body.author || 'Unknown').replace(/[\/\\:*?"<>|]/g, '_').trim();
const chStart = body.chapter_start || 1;
const chEnd = body.chapter_end || 100;
const batchIdx = body.batch_index || 1;
const totalBatches = body.total_batches || 1;
const content = body.content || '';
const qcIssues = body.qc_issues || [];
const emptyChapters = body.empty_chapters || [];

const filename = bookName + ' Ch' + String(chStart).padStart(3, '0') + '-' + chEnd + '.txt';

let qcBlock = '';
if (qcIssues.length > 0) {
  qcBlock = '\n\nQC REPORT\n' + '='.repeat(40) + '\n';
  for (const issue of qcIssues) {
    if (issue.type === 'empty') qcBlock += '[EMPTY] Chapter ' + issue.chapter + ': ' + issue.title + '\n';
    else if (issue.type === 'gap') qcBlock += '[GAP]   Missing ' + issue.missing + ' chapter(s) between Ch' + issue.from + ' and Ch' + issue.to + '\n';
  }
  qcBlock += '\nTotal issues: ' + qcIssues.length;
}

const fullContent = [
  'BOOK: ' + bookName,
  'AUTHOR: ' + author,
  'CHAPTERS: ' + chStart + '\u2013' + chEnd,
  'BATCH: ' + batchIdx + ' of ' + totalBatches,
  'WORD COUNT: ' + (body.total_words ? body.total_words.toLocaleString() : 'N/A'),
  'QC STATUS: ' + (qcIssues.length === 0 ? 'PASSED' : 'ISSUES FOUND (' + qcIssues.length + ')'),
  'EMPTY CHAPTERS: ' + (emptyChapters.length > 0 ? emptyChapters.join(', ') : 'None'),
  '',
  content,
  qcBlock,
].join('\n');

const base64 = Buffer.from(fullContent, 'utf8').toString('base64');

return [{
  json: {
    filename,
    book_name: bookName,
    author,
    chapter_start: chStart,
    chapter_end: chEnd,
    batch_index: batchIdx,
    total_batches: totalBatches,
    total_words: body.total_words || 0,
    qc_issues: qcIssues,
    qc_passed: qcIssues.length === 0,
    empty_chapters: emptyChapters,
    file_content: fullContent,
    file_b64: base64,
    file_mime: 'text/plain; charset=utf-8',
    file_ext: 'txt'
  }
}];

// Re-attach binary after folder creation (binary is lost when passing through GDrive node)
const folderResult = $input.first().json;
const fileData = $('Code: Prepare File + QC').first().json;

const buffer = Buffer.from(fileData.file_b64, 'base64');
const binaryData = await this.helpers.prepareBinaryData(
  buffer,
  fileData.filename,
  'text/plain; charset=utf-8'
);

return [{
  json: {
    ...fileData,
    folder_id: folderResult.id,
  },
  binary: {
    file_data: binaryData
  }
}];

const data = $('Code: Prepare File + QC').first().json;
let driveResult = {};
try { driveResult = $('Google Drive: Upload File').first().json; } catch (e) {}

return [{ json: {
  status: 'ok',
  message: 'Batch ' + data.batch_index + '/' + data.total_batches + ' saved to Google Drive',
  book_name: data.book_name,
  filename: data.filename,
  drive_file_id: driveResult.id || null,
  drive_web_link: driveResult.webViewLink || null,
  chapters: data.chapter_start + '\u2013' + data.chapter_end,
  total_words: data.total_words,
  qc_passed: data.qc_passed,
  qc_issues: data.qc_issues,
  empty_chapters: data.empty_chapters,
  batch_index: data.batch_index,
  total_batches: data.total_batches,
  is_last_batch: data.batch_index >= data.total_batches,
}}];
